class Channel:
    cap: int
    buf: list[int]

def new_channel(cap: int) -> Channel:
    """Empty channel of integers that holds at most cap items."""
    pre cap >= 0
    ex new_channel(2) == Channel(cap=2, buf=[])
    return Channel(cap=cap, buf=[])

def try_send(ch: Channel, v: int) -> tuple[Channel, bool]:
    """Append v if the channel has room and return (new channel, True). If it is full, return (ch, False). Never blocks."""
    post out[0].buf.len() <= out[0].cap
    ex try_send(Channel(cap=1, buf=[]), 7) == (Channel(cap=1, buf=[7]), True)
    ex try_send(Channel(cap=1, buf=[7]), 8) == (Channel(cap=1, buf=[7]), False)
    if ch.buf.len() >= ch.cap:
        return (ch, False)
    nb = ch.buf.copy()
    nb.append(v)
    return (Channel(cap=ch.cap, buf=nb), True)

def fill(ch: Channel, xs: list[int]) -> tuple[Channel, int]:
    """Try to send each element of xs in order with try_send, stopping at the first rejected send. Return the final channel and how many sends were accepted."""
    post out[1] <= xs.len() and out[1] <= ch.cap
    ex fill(Channel(cap=2, buf=[]), [1, 2, 3]) == (Channel(cap=2, buf=[1, 2]), 2)
    ex fill(Channel(cap=0, buf=[]), [5]) == (Channel(cap=0, buf=[]), 0)
    ex fill(Channel(cap=3, buf=[]), []) == (Channel(cap=3, buf=[]), 0)
    cur = ch
    n = 0
    for v in xs:
        cur, ok = try_send(cur, v)
        if not ok:
            break
        n += 1
    return (cur, n)

def accepted(cap: int, xs: list[int]) -> int uses nondet:
    """Create a channel with capacity cap and try to send each element of xs in order without blocking. Stop at the first rejected send and return how many sends were accepted."""
    pre cap >= 0
    post out <= xs.len() and out <= cap
    ch, n = fill(new_channel(cap=cap), xs)
    return n
